describe('Expand Row to View Nested Details', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should expand a row and display nested details', () => {
    // Verify table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Verify first row is visible
    cy.get('[data-testid="table-row-1"]').should('be.visible');
    cy.get('[data-testid="row-1-name"]').should('contain', 'Product A');

    // Verify expand button is visible and clickable
    cy.get('[data-testid="expand-row-btn-1"]').should('be.visible');
    cy.get('[data-testid="expand-row-btn-1"]').click();

    // Verify nested details are now visible
    cy.get('[data-testid="nested-details-row-1"]').should('be.visible');
    cy.get('[data-testid="nested-details-row-1"]').should('have.class', 'expanded');

    // Verify nested details contain expected information
    cy.get('[data-testid="nested-details-row-1"]').should('contain', 'SKU: 123');
    cy.get('[data-testid="nested-details-row-1"]').should('contain', 'Category: Electronics');

    // Verify expand button changes state (e.g., to collapse)
    cy.get('[data-testid="expand-row-btn-1"]').should('contain', 'Collapse');
  });

  it('should collapse an expanded row and hide nested details', () => {
    // Expand the first row
    cy.get('[data-testid="expand-row-btn-1"]').click();
    cy.get('[data-testid="nested-details-row-1"]').should('be.visible');

    // Verify nested details are visible before collapse
    cy.get('[data-testid="nested-details-row-1"]').should('contain', 'SKU: 123');

    // Click expand button again to collapse
    cy.get('[data-testid="expand-row-btn-1"]').click();

    // Verify nested details are now hidden
    cy.get('[data-testid="nested-details-row-1"]').should('not.exist');

    // Verify row is no longer expanded
    cy.get('[data-testid="expand-row-btn-1"]').should('contain', 'Expand');

    // Verify other rows are still visible
    cy.get('[data-testid="table-row-2"]').should('be.visible');
  });
});
